import {NextResponse} from 'next/server';
import {getSupabaseServer,requireUser} from '../../../../lib/supabase/server';
export const runtime='nodejs';
function isAdmin(user){return user?.user_metadata?.role==='admin'||user?.app_metadata?.role==='admin'}
export async function GET(request){try{const u=await requireUser(request);if(!isAdmin(u))return NextResponse.json({error:'Admin access required.'},{status:403});const db=getSupabaseServer();const{data,error}=await db.from('vendors').select('id,name,description,contact_email,phone,address,status,created_at').order('created_at',{ascending:false});if(error)throw error;return NextResponse.json({vendors:data||[]})}catch(e){return NextResponse.json({error:e.message==='Unauthorized'?'Unauthorized.':e.message},{status:e.message==='Unauthorized'?401:500})}}
export async function PATCH(request){try{const u=await requireUser(request);if(!isAdmin(u))return NextResponse.json({error:'Admin access required.'},{status:403});const b=await request.json();if(!['Pending','Active','Suspended'].includes(b.status))return NextResponse.json({error:'Invalid vendor status.'},{status:400});const db=getSupabaseServer();const{data,error}=await db.from('vendors').update({status:b.status}).eq('id',b.vendor_id).select().single();if(error)throw error;return NextResponse.json({vendor:data})}catch(e){return NextResponse.json({error:e.message==='Unauthorized'?'Unauthorized.':e.message},{status:e.message==='Unauthorized'?401:400})}}
